      SUBROUTINE RDNEXTC---- FIND NEXT NON-BLANK INPUT CHARACTERC-------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'C-------------------------------------------------------------------C     COMMON /NCHRS/  NCHRS      DATA NCHRS /0/C    5 CONTINUE      IF (ICOL .GT. 80) THEN        CALL RDLINE        IF (ENDFIL) GO TO 100        NCHRS = 0      ENDIF   10 CONTINUE      IMARK = ICOL + 1   20 CALL RDFWRD      IF (ITEM .EQ. BLANK) GO TO 20      NCHRS = NCHRS + 1      IF (ITEM .EQ. '&') THEN        CALL RDLINE        IF (ENDFIL) GO TO 100        NCHRS = 0        GO TO 10      ENDIF      IF (ICOL .LE. 80) IMARK = ICOL      IF (ITEM .EQ. '!') THEN        ICOL = 81        ITEM = KLINE(ICOL)        IF (NCHRS .EQ. 1) GO TO 5      ENDIFC  100 CONTINUE      RETURN      END